<script>
document.addEventListener('DOMContentLoaded',()=>{const $id=id=>document.getElementById(id),age=['<7','7_28','29d_1y','1_4y','5_14y','15_24y','25_44y','45_64y','65plus'],cols=[{data:'no'},{data:'kd_penyakit'},{data:'nm_penyakit'}];age.forEach(a=>{cols.push({data:a+'_l',className:'text-right'});cols.push({data:a+'_p',className:'text-right'})});cols.push({data:'total_l',className:'text-right font-weight-bold'},{data:'total_p',className:'text-right font-weight-bold'},{data:'total',className:'text-right font-weight-bold'});let table=$('#morbidTable').DataTable({processing:true,serverSide:false,orderCellsTop:true,autoWidth:false,pageLength:25,lengthMenu:[10,25,50,100],dom:'lBfrtip',buttons:[{extend:'copyHtml5',text:'Copy',exportOptions:{columns:':visible'}},{extend:'excelHtml5',text:'Excel',filename:'morbiditas_rajal',exportOptions:{columns:':visible'}}],columns:cols,order:[[23,'desc']],language:{info:'Menampilkan _START_ sampai _END_ dari _TOTAL_ diagnosis',lengthMenu:'Tampilkan _MENU_ diagnosis',search:'Cari:',zeroRecords:'Data tidak ditemukan',emptyTable:'Belum ada data'}});function error(m){$id('morbidAlert').textContent=m;$id('morbidAlert').className='alert alert-danger'}function load(){const a=$id('morbidStart').value,b=$id('morbidEnd').value;if(!a||!b||a>b)return error('Rentang tanggal tidak valid.');const body=new URLSearchParams({tgl1:a,tgl2:b});Array.from($id('morbidPoli').selectedOptions).forEach(o=>body.append('kd_poli[]',o.value));fetch('api/morbiditas-rajal.php',{method:'POST',body,headers:{Accept:'application/json'}}).then(r=>r.json().then(j=>({r,j}))).then(({r,j})=>{if(!r.ok||!j.ok)throw Error(j.message||'Gagal memuat data.');table.clear().rows.add(j.data).draw();$id('morbidContext').textContent=a+' s.d. '+b+' • '+j.data.length+' diagnosis'}).catch(e=>error(e.message))}fetch('api/icd-poli-list.php').then(r=>r.json()).then(j=>{(j.data||j||[]).forEach(p=>$id('morbidPoli').add(new Option(p.nm_poli||p.label,p.kd_poli||p.value)));load()}).catch(e=>error('Gagal memuat daftar poli.'));$id('morbidApply').onclick=load;$id('morbidReset').onclick=()=>{Array.from($id('morbidPoli').options).forEach(o=>o.selected=false);$id('morbidStart').value=$id('morbidStart').defaultValue;$id('morbidEnd').value=$id('morbidEnd').defaultValue;load()};});
</script>












